DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.fiscal_environment_marker WHERE project_ref='swzpzcwiasxmjutrmvkm') OR EXISTS(SELECT 1 FROM public.fiscal_environment_marker WHERE project_ref<>'swzpzcwiasxmjutrmvkm') THEN RAISE EXCEPTION 'canonical_project_required'; END IF; END $$;
CREATE OR REPLACE FUNCTION platform_private.b2b_internal_commercial_actor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $f$ SELECT auth.uid() IS NOT NULL AND public.h15_actor_organization() IS NOT NULL AND platform_private.platform_actor_access_ready(auth.uid()) AND (public.has_role(auth.uid(),'administrador'::public.app_role) OR public.has_role(auth.uid(),'gestor_comercial'::public.app_role)) AND NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role IN ('parceiro_b2b','parceiro_b2b_tecnico')); $f$;
REVOKE ALL ON FUNCTION platform_private.b2b_internal_commercial_actor() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION platform_private.b2b_internal_commercial_actor() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION platform_private.b2b_assignment_identity_coherent(p_user uuid,p_partner uuid,p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $f$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=p_user AND p.organization_id=p_owner AND p.ativo IS TRUE AND platform_private.platform_actor_access_ready(p_user)) AND (SELECT count(*) FROM public.user_roles r WHERE r.user_id=p_user)=1 AND (SELECT count(*) FROM public.partner_users pu WHERE pu.user_id=p_user)=1 AND EXISTS(SELECT 1 FROM public.partner_users pu JOIN public.user_roles r ON r.user_id=pu.user_id WHERE pu.user_id=p_user AND pu.partner_id=p_partner AND ((r.role='parceiro_b2b' AND pu.papel='gestor') OR (r.role='parceiro_b2b_tecnico' AND pu.papel='tecnico'))); $f$;
REVOKE ALL ON FUNCTION platform_private.b2b_assignment_identity_coherent(uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION platform_private.b2b_assignment_identity_coherent(uuid,uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_b2b_user_clients_secure(p_user_id uuid DEFAULT NULL,p_search text DEFAULT NULL) RETURNS TABLE(cliente_id uuid,nome text,razao_social text,nome_fantasia text,tipo_pessoa text,documento_mascarado text,telefone text,cidade text,estado text,assignment_type text,can_create_simulation boolean,can_monitor boolean,assigned_at timestamptz,ultima_simulacao_at timestamptz,total_simulacoes bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $f$
DECLARE org uuid:=public.h15_actor_organization(); BEGIN
IF NOT platform_private.b2b_internal_commercial_actor() THEN RAISE EXCEPTION 'b2b_client_assignments_unavailable' USING ERRCODE='42501'; END IF;
IF p_search IS NOT NULL AND length(p_search)>200 THEN RAISE EXCEPTION 'invalid_search' USING ERRCODE='22023'; END IF;
IF p_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=p_user_id AND p.organization_id=org AND p.ativo IS TRUE) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
RETURN QUERY SELECT c.id,c.nome,c.razao_social,c.nome_fantasia,c.tipo_pessoa::text,CASE WHEN c.cpf_cnpj IS NULL THEN NULL WHEN length(c.cpf_cnpj)>=4 THEN repeat('*',greatest(length(c.cpf_cnpj)-4,0))||right(c.cpf_cnpj,4) ELSE '****' END,c.telefone,c.endereco_municipio,c.endereco_estado,puc.assignment_type,puc.can_create_simulation,puc.can_monitor,puc.assigned_at,(SELECT max(ps.created_at) FROM public.partner_simulations ps WHERE ps.cliente_id=c.id AND ps.partner_id=puc.partner_id AND ps.created_by=puc.user_id),(SELECT count(*) FROM public.partner_simulations ps WHERE ps.cliente_id=c.id AND ps.partner_id=puc.partner_id AND ps.created_by=puc.user_id) FROM public.partner_user_clients puc JOIN public.clientes c ON c.id=puc.cliente_id JOIN public.partner_accounts pa ON pa.id=puc.partner_id WHERE puc.active IS TRUE AND (p_user_id IS NULL OR puc.user_id=p_user_id) AND c.organization_id=org AND pa.commercial_owner_organization_id=org AND pa.ativo IS TRUE AND pa.deleted_at IS NULL AND platform_private.b2b_assignment_identity_coherent(puc.user_id,puc.partner_id,org) AND (p_search IS NULL OR p_search='' OR coalesce(c.nome,'') ILIKE '%'||p_search||'%' OR coalesce(c.razao_social,'') ILIKE '%'||p_search||'%' OR coalesce(c.nome_fantasia,'') ILIKE '%'||p_search||'%' OR coalesce(c.endereco_municipio,'') ILIKE '%'||p_search||'%'); END $f$;
REVOKE ALL ON FUNCTION public.get_b2b_user_clients_secure(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_b2b_user_clients_secure(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.rpc_message_set_status(p_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
DECLARE org uuid:=public.h15_actor_organization(); ctx jsonb; resource record; internal boolean; BEGIN
IF org IS NULL OR NOT platform_private.platform_actor_access_ready(auth.uid()) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
internal:=platform_private.b2b_internal_commercial_actor(); IF NOT internal THEN ctx:=platform_private.b2b_commercial_context(); IF ctx IS NULL OR ctx->>'role'<>'parceiro_b2b' OR ctx->>'mode'<>'commercial_owner' THEN RAISE EXCEPTION 'b2b_messages_unavailable' USING ERRCODE='42501'; END IF; END IF;
SELECT m.id,po.partner_id,pa.commercial_owner_organization_id,po.cliente_id INTO resource FROM public.partner_order_messages m JOIN public.partner_orders po ON po.id=m.order_id JOIN public.partner_accounts pa ON pa.id=po.partner_id WHERE m.id=p_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL FOR UPDATE OF m,po,pa;
IF resource.id IS NULL OR resource.commercial_owner_organization_id IS DISTINCT FROM org OR (NOT internal AND resource.partner_id IS DISTINCT FROM (ctx->>'partner_id')::uuid) OR (resource.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=resource.cliente_id AND c.organization_id=org)) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
IF p_status IS NULL OR p_status NOT IN ('nao_lida','lida','respondida','encerrada') THEN RAISE EXCEPTION 'invalid_status' USING ERRCODE='22023'; END IF;
UPDATE public.partner_order_messages SET status=p_status,status_updated_at=now() WHERE id=resource.id; END $f$;
REVOKE ALL ON FUNCTION public.rpc_message_set_status(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rpc_message_set_status(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION platform_private.b2b_partner_logo_write_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $f$ SELECT NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role IN ('parceiro_b2b','parceiro_b2b_tecnico')) OR COALESCE(platform_private.b2b_commercial_context()->>'mode'='legacy_partner_tenant' AND platform_private.b2b_commercial_context()->>'role'='parceiro_b2b',false); $f$;
REVOKE ALL ON FUNCTION platform_private.b2b_partner_logo_write_allowed() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION platform_private.b2b_partner_logo_write_allowed() TO authenticated,service_role;
DROP POLICY IF EXISTS b2b_commercial_logo_insert_containment ON storage.objects; CREATE POLICY b2b_commercial_logo_insert_containment ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'logos' OR platform_private.b2b_partner_logo_write_allowed());
DROP POLICY IF EXISTS b2b_commercial_logo_update_containment ON storage.objects; CREATE POLICY b2b_commercial_logo_update_containment ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id<>'logos' OR platform_private.b2b_partner_logo_write_allowed()) WITH CHECK(bucket_id<>'logos' OR platform_private.b2b_partner_logo_write_allowed());
DROP POLICY IF EXISTS b2b_commercial_logo_delete_containment ON storage.objects; CREATE POLICY b2b_commercial_logo_delete_containment ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id<>'logos' OR platform_private.b2b_partner_logo_write_allowed());